from __future__ import annotations

"""Domain models for Stripe Connect destination charges and their refunds.

Everything here is integer cents. A destination charge moves money from a
buyer to the platform, takes an ``application_fee_amount`` for the platform,
and transfers the rest to a connected seller account. When a refund is issued
the platform must decide how much of the application fee it gives back and how
much of the transfer to the seller it reverses.
"""

from dataclasses import dataclass, field


def _require_id(label: str, value: str) -> str:
    text = (value or "").strip()
    if not text:
        raise ValueError(f"{label} is required")
    return text


def _require_currency(value: str) -> str:
    text = (value or "").strip().lower()
    if len(text) != 3:
        raise ValueError("currency must be a 3-letter code")
    return text


@dataclass(frozen=True)
class ConnectedAccount:
    """A seller account that receives transfers from destination charges."""

    account_id: str
    display_name: str
    country: str

    def __post_init__(self) -> None:
        object.__setattr__(self, "account_id", _require_id("account_id", self.account_id))
        object.__setattr__(self, "display_name", _require_id("display_name", self.display_name))
        country = _require_id("country", self.country).upper()
        if len(country) != 2:
            raise ValueError("country must be a 2-letter code")
        object.__setattr__(self, "country", country)


@dataclass(frozen=True)
class MarketplaceCharge:
    """A captured destination charge split between platform and one seller.

    ``amount_cents`` is the gross amount the buyer paid. ``application_fee_cents``
    is the platform's cut. The remainder (``amount - application_fee``) is the
    transfer that landed in the connected account's balance.
    """

    charge_id: str
    seller: ConnectedAccount
    amount_cents: int
    application_fee_cents: int
    currency: str
    captured: bool = True

    def __post_init__(self) -> None:
        object.__setattr__(self, "charge_id", _require_id("charge_id", self.charge_id))
        object.__setattr__(self, "currency", _require_currency(self.currency))
        if self.amount_cents <= 0:
            raise ValueError("amount_cents must be positive")
        if self.application_fee_cents < 0:
            raise ValueError("application_fee_cents must be non-negative")
        if self.application_fee_cents > self.amount_cents:
            raise ValueError("application_fee_cents cannot exceed amount_cents")

    @property
    def transfer_cents(self) -> int:
        """Amount that was transferred to the connected seller account."""

        return self.amount_cents - self.application_fee_cents


@dataclass(frozen=True)
class RefundRequest:
    """A request to refund part (or all) of a marketplace charge.

    ``refund_id`` is the caller-supplied idempotency key. Two requests with the
    same id must produce the same outcome and must not double-apply.
    """

    refund_id: str
    charge_id: str
    amount_cents: int
    reason: str = "requested_by_customer"

    def __post_init__(self) -> None:
        object.__setattr__(self, "refund_id", _require_id("refund_id", self.refund_id))
        object.__setattr__(self, "charge_id", _require_id("charge_id", self.charge_id))
        object.__setattr__(self, "reason", _require_id("reason", self.reason))
        if self.amount_cents <= 0:
            raise ValueError("refund amount_cents must be positive")


@dataclass(frozen=True)
class ReversalSplit:
    """How a single refund is split between platform fee and seller transfer.

    ``fee_reversal_cents`` comes out of the platform's application fee.
    ``transfer_reversal_cents`` is clawed back from the seller's balance.
    The two must add up to the refunded amount exactly.
    """

    refund_amount_cents: int
    fee_reversal_cents: int
    transfer_reversal_cents: int

    def __post_init__(self) -> None:
        if self.refund_amount_cents <= 0:
            raise ValueError("refund_amount_cents must be positive")
        if self.fee_reversal_cents < 0:
            raise ValueError("fee_reversal_cents must be non-negative")
        if self.transfer_reversal_cents < 0:
            raise ValueError("transfer_reversal_cents must be non-negative")

    def reconciles(self) -> bool:
        return self.fee_reversal_cents + self.transfer_reversal_cents == self.refund_amount_cents


@dataclass(frozen=True)
class RefundRecord:
    """The persisted result of applying one refund against a charge."""

    refund_id: str
    charge_id: str
    amount_cents: int
    fee_reversal_cents: int
    transfer_reversal_cents: int
    status: str
    reason: str

    def __post_init__(self) -> None:
        object.__setattr__(self, "refund_id", _require_id("refund_id", self.refund_id))
        object.__setattr__(self, "charge_id", _require_id("charge_id", self.charge_id))
        if self.status not in {"succeeded", "rejected"}:
            raise ValueError("status must be succeeded or rejected")


@dataclass
class ChargeBalances:
    """Mutable running balances for one charge as refunds accumulate.

    Tracks how much of the gross amount, the application fee, and the seller
    transfer remain reversible. A new refund may never push any of these
    negative.
    """

    charge_id: str
    refundable_amount_cents: int
    reversible_fee_cents: int
    reversible_transfer_cents: int
    records: list[RefundRecord] = field(default_factory=list)

    @classmethod
    def from_charge(cls, charge: MarketplaceCharge) -> "ChargeBalances":
        return cls(
            charge_id=charge.charge_id,
            refundable_amount_cents=charge.amount_cents,
            reversible_fee_cents=charge.application_fee_cents,
            reversible_transfer_cents=charge.transfer_cents,
        )

    def refunded_so_far_cents(self) -> int:
        return sum(r.amount_cents for r in self.records if r.status == "succeeded")

    def fee_reversed_so_far_cents(self) -> int:
        return sum(r.fee_reversal_cents for r in self.records if r.status == "succeeded")

