from __future__ import annotations

"""Pro-rata allocation of a refund across application fee and seller transfer.

When a marketplace refunds part of a destination charge, the money has to come
out of two buckets in proportion to how they were funded:

    fee_fraction = application_fee / amount
    transfer_fraction = transfer / amount

A refund of ``R`` cents should reverse ``R * fee_fraction`` of the platform fee
and ``R * transfer_fraction`` of the seller transfer. Because money is integer
cents, the two pieces have to be rounded so they still sum to exactly ``R`` --
no cent may be lost or invented.
"""

from money_models import MarketplaceCharge, ReversalSplit


def fee_fraction(charge: MarketplaceCharge) -> float:
    """Share of the gross charge that was the platform application fee."""

    if charge.amount_cents <= 0:
        raise ValueError("charge amount must be positive")
    return charge.application_fee_cents / charge.amount_cents


def transfer_fraction(charge: MarketplaceCharge) -> float:
    """Share of the gross charge that went to the connected seller."""

    return 1.0 - fee_fraction(charge)


def _round_half_up(value: float) -> int:
    """Round to nearest integer, halves going up (banker's rounding is wrong here)."""

    floor_part = int(value)
    remainder = value - floor_part
    if value < 0:
        # Symmetric handling for completeness; refunds are never negative.
        if -remainder >= 0.5:
            return floor_part - 1
        return floor_part
    if remainder >= 0.5:
        return floor_part + 1
    return floor_part


def split_refund(charge: MarketplaceCharge, refund_amount_cents: int) -> ReversalSplit:
    """Allocate ``refund_amount_cents`` across fee and transfer pro-rata.

    The fee reversal is the rounded pro-rata share of the application fee. The
    transfer reversal is rounded independently from the transfer fraction.
    """

    if refund_amount_cents <= 0:
        raise ValueError("refund_amount_cents must be positive")

    ff = fee_fraction(charge)
    tf = transfer_fraction(charge)

    fee_reversal = _round_half_up(refund_amount_cents * ff)
    transfer_reversal = _round_half_up(refund_amount_cents * tf)

    return ReversalSplit(
        refund_amount_cents=refund_amount_cents,
        fee_reversal_cents=fee_reversal,
        transfer_reversal_cents=transfer_reversal,
    )


def split_full_refund(charge: MarketplaceCharge) -> ReversalSplit:
    """A full refund reverses the entire fee and the entire transfer."""

    return ReversalSplit(
        refund_amount_cents=charge.amount_cents,
        fee_reversal_cents=charge.application_fee_cents,
        transfer_reversal_cents=charge.transfer_cents,
    )


def proportional_fee_reversal(charge: MarketplaceCharge, refund_amount_cents: int) -> int:
    """Convenience helper returning only the fee portion of a split."""

    return split_refund(charge, refund_amount_cents).fee_reversal_cents


def proportional_transfer_reversal(charge: MarketplaceCharge, refund_amount_cents: int) -> int:
    """Convenience helper returning only the transfer portion of a split."""

    return split_refund(charge, refund_amount_cents).transfer_reversal_cents


def describe_split(charge: MarketplaceCharge, refund_amount_cents: int) -> dict[str, object]:
    """Human-readable breakdown used by support and finance tooling."""

    split = split_refund(charge, refund_amount_cents)
    return {
        "charge_id": charge.charge_id,
        "refund_amount_cents": split.refund_amount_cents,
        "fee_reversal_cents": split.fee_reversal_cents,
        "transfer_reversal_cents": split.transfer_reversal_cents,
        "fee_fraction": round(fee_fraction(charge), 6),
        "transfer_fraction": round(transfer_fraction(charge), 6),
        "reconciles": split.reconciles(),
    }


def split_many(charge: MarketplaceCharge, amounts: list[int]) -> list[ReversalSplit]:
    """Split a sequence of refund amounts against the same charge.

    This does not track running balances; it is a stateless preview used by the
    dashboard when an operator types several proposed partial refunds at once.
    """

    splits: list[ReversalSplit] = []
    for amount in amounts:
        splits.append(split_refund(charge, amount))
    return splits


def total_fee_reversal(charge: MarketplaceCharge, amounts: list[int]) -> int:
    """Sum the fee portions of several proposed refunds."""

    return sum(split.fee_reversal_cents for split in split_many(charge, amounts))


def total_transfer_reversal(charge: MarketplaceCharge, amounts: list[int]) -> int:
    """Sum the transfer portions of several proposed refunds."""

    return sum(split.transfer_reversal_cents for split in split_many(charge, amounts))


def all_splits_reconcile(charge: MarketplaceCharge, amounts: list[int]) -> bool:
    """True when every proposed refund split sums back to its own amount."""

    return all(split.reconciles() for split in split_many(charge, amounts))

