from __future__ import annotations

"""Tracks accumulated refunds per charge and produces each reversal split.

A charge can be refunded several times. Each partial refund draws down three
running balances: the refundable gross amount, the reversible application fee,
and the reversible seller transfer. The ledger is the single place that knows
how much of each bucket is left, so successive refunds stay inside the original
amounts.

The ledger consumes the pro-rata split produced by ``proportional_split`` and
records what was actually reversed.
"""

from money_models import (
    ChargeBalances,
    MarketplaceCharge,
    RefundRecord,
    RefundRequest,
    ReversalSplit,
)
from proportional_split import split_full_refund, split_refund


class RefundLedger:
    """In-memory ledger keyed by charge id.

    Holds a :class:`ChargeBalances` per charge and a map of already-applied
    refund ids for idempotency.
    """

    def __init__(self) -> None:
        self._balances: dict[str, ChargeBalances] = {}
        self._charges: dict[str, MarketplaceCharge] = {}
        self._applied: dict[str, RefundRecord] = {}

    def register_charge(self, charge: MarketplaceCharge) -> None:
        if charge.charge_id not in self._balances:
            self._charges[charge.charge_id] = charge
            self._balances[charge.charge_id] = ChargeBalances.from_charge(charge)

    def balances_for(self, charge_id: str) -> ChargeBalances:
        if charge_id not in self._balances:
            raise KeyError(f"unknown charge {charge_id}")
        return self._balances[charge_id]

    def charge_for(self, charge_id: str) -> MarketplaceCharge:
        if charge_id not in self._charges:
            raise KeyError(f"unknown charge {charge_id}")
        return self._charges[charge_id]

    def existing_record(self, refund_id: str) -> RefundRecord | None:
        return self._applied.get(refund_id)

    def _is_full_remaining_refund(self, balances: ChargeBalances, amount: int) -> bool:
        return amount == balances.refundable_amount_cents

    def plan_split(self, charge: MarketplaceCharge, balances: ChargeBalances, amount: int) -> ReversalSplit:
        """Decide how a refund of ``amount`` should be split right now.

        A refund that clears the entire remaining balance reverses whatever fee
        and transfer are still reversible. A partial refund is allocated
        pro-rata against the original charge.
        """

        if self._is_full_remaining_refund(balances, amount):
            return ReversalSplit(
                refund_amount_cents=amount,
                fee_reversal_cents=balances.reversible_fee_cents,
                transfer_reversal_cents=balances.reversible_transfer_cents,
            )
        return split_refund(charge, amount)

    def apply(self, request: RefundRequest) -> RefundRecord:
        """Apply a refund request, returning the resulting record.

        Idempotent on ``refund_id``. The split is drawn down from the running
        balances so later refunds cannot over-reverse.
        """

        prior = self._applied.get(request.refund_id)
        if prior is not None:
            return prior

        charge = self.charge_for(request.charge_id)
        balances = self.balances_for(request.charge_id)

        split = self.plan_split(charge, balances, request.amount_cents)

        record = RefundRecord(
            refund_id=request.refund_id,
            charge_id=request.charge_id,
            amount_cents=request.amount_cents,
            fee_reversal_cents=split.fee_reversal_cents,
            transfer_reversal_cents=split.transfer_reversal_cents,
            status="succeeded",
            reason=request.reason,
        )

        balances.refundable_amount_cents -= request.amount_cents
        balances.reversible_transfer_cents -= split.transfer_reversal_cents
        balances.records.append(record)
        self._applied[request.refund_id] = record
        return record

    def record_rejected(self, request: RefundRequest, reason: str) -> RefundRecord:
        record = RefundRecord(
            refund_id=request.refund_id,
            charge_id=request.charge_id,
            amount_cents=request.amount_cents,
            fee_reversal_cents=0,
            transfer_reversal_cents=0,
            status="rejected",
            reason=reason,
        )
        self._applied[request.refund_id] = record
        return record

    def all_records(self, charge_id: str) -> list[RefundRecord]:
        return list(self.balances_for(charge_id).records)


def remaining_refundable_cents(ledger: RefundLedger, charge_id: str) -> int:
    return ledger.balances_for(charge_id).refundable_amount_cents


def remaining_reversible_fee_cents(ledger: RefundLedger, charge_id: str) -> int:
    return ledger.balances_for(charge_id).reversible_fee_cents


def remaining_reversible_transfer_cents(ledger: RefundLedger, charge_id: str) -> int:
    return ledger.balances_for(charge_id).reversible_transfer_cents

