from __future__ import annotations

"""Public entry point for issuing marketplace refunds.

Wires validation, the ledger, and serialization together. Callers register a
charge once, then issue one or more refund requests. Each call returns a plain
dict; repeated calls with the same ``refund_id`` return the same outcome
without re-applying.
"""

from charge_catalog import lookup_charge
from money_models import MarketplaceCharge, RefundRequest
from reconciliation import reconcile_charge
from refund_ledger import RefundLedger
from refund_validation import RefundValidationError, validate_refund
from serializers import balances_to_dict, record_to_dict, refund_history


class MarketplaceRefundService:
    """Stateful refund coordinator backed by a single :class:`RefundLedger`."""

    def __init__(self) -> None:
        self.ledger = RefundLedger()

    def register_charge(self, charge: MarketplaceCharge) -> None:
        self.ledger.register_charge(charge)

    def register_charge_id(self, charge_id: str) -> MarketplaceCharge:
        charge = lookup_charge(charge_id)
        self.ledger.register_charge(charge)
        return charge

    def issue_refund(self, request: RefundRequest) -> dict[str, object]:
        """Issue one refund. Idempotent on ``request.refund_id``."""

        existing = self.ledger.existing_record(request.refund_id)
        if existing is not None:
            return record_to_dict(existing)

        try:
            validate_refund(self.ledger, request)
        except RefundValidationError as exc:
            record = self.ledger.record_rejected(request, exc.code)
            return record_to_dict(record)

        record = self.ledger.apply(request)
        return record_to_dict(record)

    def balances(self, charge_id: str) -> dict[str, object]:
        return balances_to_dict(self.ledger, charge_id)

    def history(self, charge_id: str) -> list[dict[str, object]]:
        return refund_history(self.ledger, charge_id)

    def reconcile(self, charge_id: str) -> dict[str, object]:
        charge = self.ledger.charge_for(charge_id)
        return reconcile_charge(self.ledger, charge)


def issue_single_refund(charge: MarketplaceCharge, request: RefundRequest) -> dict[str, object]:
    """One-shot helper: register a charge and apply a single refund."""

    service = MarketplaceRefundService()
    service.register_charge(charge)
    return service.issue_refund(request)

