from __future__ import annotations

"""Guard rails that run before a refund touches the ledger.

These checks protect the two hard invariants of a Connect refund:

* total refunded across every partial may never exceed the original charge;
* the application fee given back may never exceed the original fee.

Validation only inspects state. It never mutates balances.
"""

from money_models import MarketplaceCharge, RefundRequest
from proportional_split import split_refund
from refund_ledger import RefundLedger


class RefundValidationError(ValueError):
    """Raised when a refund request would break a money invariant."""

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code


def check_amount_positive(request: RefundRequest) -> None:
    if request.amount_cents <= 0:
        raise RefundValidationError("non_positive_amount", "refund amount must be positive")


def check_not_over_refunding(ledger: RefundLedger, request: RefundRequest) -> None:
    """Reject a refund that would push total refunds past the gross charge."""

    remaining = ledger.balances_for(request.charge_id).refundable_amount_cents
    if request.amount_cents > remaining:
        raise RefundValidationError(
            "over_refund",
            f"refund of {request.amount_cents} exceeds remaining {remaining}",
        )


def check_fee_reversal_within_cap(ledger: RefundLedger, request: RefundRequest) -> None:
    """Reject a refund whose fee reversal would exceed the reversible fee left."""

    charge = ledger.charge_for(request.charge_id)
    balances = ledger.balances_for(request.charge_id)
    planned = ledger.plan_split(charge, balances, request.amount_cents)
    if planned.fee_reversal_cents > balances.reversible_fee_cents:
        raise RefundValidationError(
            "fee_over_reversal",
            "fee reversal would exceed remaining reversible application fee",
        )


def validate_refund(ledger: RefundLedger, request: RefundRequest) -> None:
    """Run all guard rails for a refund request in order."""

    check_amount_positive(request)
    if request.charge_id not in ledger._balances:  # noqa: SLF001 - small internal ledger
        raise RefundValidationError("unknown_charge", f"unknown charge {request.charge_id}")
    check_not_over_refunding(ledger, request)
    check_fee_reversal_within_cap(ledger, request)


def preview_validation(ledger: RefundLedger, request: RefundRequest) -> dict[str, object]:
    """Non-raising preview used by the dashboard to grey-out bad refunds."""

    problems: list[str] = []
    try:
        check_amount_positive(request)
    except RefundValidationError as exc:
        problems.append(exc.code)
    if request.charge_id not in ledger._balances:  # noqa: SLF001
        problems.append("unknown_charge")
        return {"ok": False, "problems": problems}
    try:
        check_not_over_refunding(ledger, request)
    except RefundValidationError as exc:
        problems.append(exc.code)
    try:
        check_fee_reversal_within_cap(ledger, request)
    except RefundValidationError as exc:
        problems.append(exc.code)
    return {"ok": not problems, "problems": problems}

